import * as THREE from "three";
import { mergeGeometries } from "three/addons/utils/BufferGeometryUtils.js";

// Reconstructed from the linked An Nhien reference photographs, not a scan.
export const BEAD_COUNT = 21;
export const RING_RADIUS = 1.34;

// Generated by scripts/bake-materials.cjs. Decode small files instead of
// calculating millions of noise samples on the UI thread when a scene appears.
export function surfaceTextures(
  kind: "wood" | "powder" | "ceramic",
  onLoad: () => void = () => {},
) {
  const loader = new THREE.TextureLoader();
  const load = (channel: string) => {
    const texture = loader.load(
      `/editorial/materials/${kind}-${channel}.webp`,
      onLoad,
    );
    texture.wrapS = texture.wrapT = THREE.RepeatWrapping;
    return texture;
  };
  const map = load("color");
  map.colorSpace = THREE.SRGBColorSpace;
  return { map, bump: load("bump"), roughness: load("roughness") };
}

export function drilledBeadGeometry() {
  const cut = 0.125,
    radius = 0.198,
    hole = radius * Math.sin(cut);
  const outside = new THREE.SphereGeometry(
    radius,
    48,
    32,
    0,
    Math.PI * 2,
    cut,
    Math.PI - cut * 2,
  );
  const inside = new THREE.CylinderGeometry(
    hole,
    hole,
    radius * Math.cos(cut) * 2,
    24,
    1,
    true,
  );
  inside.scale(-1, 1, 1);
  const geometry = mergeGeometries([outside, inside]);
  outside.dispose();
  inside.dispose();
  return geometry;
}

function part(
  geometry: THREE.BufferGeometry,
  material: THREE.Material,
  position: [number, number, number] = [0, 0, 0],
) {
  const m = new THREE.Mesh(geometry, material);
  m.position.set(...position);
  m.castShadow = m.receiveShadow = true;
  return m;
}

function lidPerforations() {
  const canvas = document.createElement("canvas");
  canvas.width = 1024;
  canvas.height = 512;
  const ctx = canvas.getContext("2d")!;
  ctx.fillStyle = "white";
  ctx.fillRect(0, 0, 1024, 512);
  ctx.fillStyle = "black";
  // Open lotus-petal vents, distributed around a curved lid.
  for (let row = 0; row < 2; row++)
    for (let i = 0; i < 18; i++) {
      const x = ((i + (row ? 0.5 : 0)) / 18) * 1024,
        y = row ? 300 : 195;
      ctx.beginPath();
      ctx.moveTo(x, y - 45);
      ctx.bezierCurveTo(x + 28, y - 12, x + 29, y + 16, x, y + 43);
      ctx.bezierCurveTo(x - 29, y + 16, x - 28, y - 12, x, y - 45);
      ctx.fill();
    }
  const map = new THREE.CanvasTexture(canvas);
  map.wrapS = THREE.RepeatWrapping;
  return map;
}

export function referenceBurner(ceramic: THREE.MeshPhysicalMaterial) {
  const group = new THREE.Group();
  const profile = [
    new THREE.Vector2(0.0, 0.13),
    new THREE.Vector2(0.46, 0.13),
    new THREE.Vector2(0.66, 0.19),
    new THREE.Vector2(0.78, 0.33),
    new THREE.Vector2(0.79, 0.41),
    new THREE.Vector2(0.72, 0.54),
    new THREE.Vector2(0.66, 0.62),
    new THREE.Vector2(0.67, 0.7),
    new THREE.Vector2(0.7, 0.73),
    new THREE.Vector2(0.7, 0.78),
    new THREE.Vector2(0.64, 0.78),
    new THREE.Vector2(0.63, 0.69),
    new THREE.Vector2(0.62, 0.6),
    new THREE.Vector2(0.7, 0.46),
    new THREE.Vector2(0.7, 0.34),
    new THREE.Vector2(0.57, 0.25),
    new THREE.Vector2(0, 0.24),
  ];
  group.add(
    part(
      new THREE.LatheGeometry(new THREE.SplineCurve(profile).getPoints(96), 96),
      ceramic,
    ),
  );
  const lidGeometry = new THREE.SphereGeometry(
    0.625,
    96,
    48,
    0,
    Math.PI * 2,
    0,
    Math.PI / 2,
  );
  lidGeometry.scale(1, 0.43, 1);
  lidGeometry.translate(0, 0.79, 0);
  const lidMaterial = ceramic.clone();
  lidMaterial.alphaMap = lidPerforations();
  lidMaterial.alphaTest = 0.5;
  lidMaterial.side = THREE.DoubleSide;
  const lid = part(lidGeometry, lidMaterial);
  group.add(lid);
  const rim = part(
    new THREE.TorusGeometry(0.625, 0.017, 12, 96),
    ceramic,
    [0, 0.79, 0],
  );
  rim.rotation.x = Math.PI / 2;
  group.add(rim);
  const knobProfile = [
    new THREE.Vector2(0, 0),
    new THREE.Vector2(0.065, 0),
    new THREE.Vector2(0.07, 0.045),
    new THREE.Vector2(0.13, 0.115),
    new THREE.Vector2(0.115, 0.165),
    new THREE.Vector2(0.065, 0.205),
    new THREE.Vector2(0, 0.22),
  ];
  group.add(
    part(
      new THREE.LatheGeometry(
        new THREE.SplineCurve(knobProfile).getPoints(40),
        48,
      ),
      ceramic,
      [0, 1.045, 0],
    ),
  );
  for (let i = 0; i < 3; i++) {
    const a = (i / 3) * Math.PI * 2 + Math.PI / 6;
    const foot = part(new THREE.CylinderGeometry(0.17, 0.1, 0.21, 6), ceramic, [
      Math.sin(a) * 0.52,
      0.105,
      Math.cos(a) * 0.52,
    ]);
    foot.scale.set(1, 1, 0.78);
    foot.rotation.y = a;
    group.add(foot);
  }
  return group;
}

export function referenceCones(
  powder: THREE.MeshStandardMaterial,
  trayMaterial: THREE.Material,
) {
  const group = new THREE.Group();
  const tray = part(
    new THREE.CylinderGeometry(0.85, 0.79, 0.06, 64),
    trayMaterial,
  );
  group.add(tray);
  const rim = part(
    new THREE.TorusGeometry(0.81, 0.034, 12, 80),
    trayMaterial,
    [0, 0.04, 0],
  );
  rim.rotation.x = Math.PI / 2;
  group.add(rim);
  const geometry = new THREE.CylinderGeometry(
    0.027,
    0.135,
    0.65,
    48,
    24,
    false,
  );
  const positions = geometry.attributes.position;
  for (let i = 0; i < positions.count; i++) {
    const x = positions.getX(i),
      y = positions.getY(i),
      z = positions.getZ(i),
      a = Math.atan2(z, x);
    const lobe = 1 + Math.cos(a * 6) * 0.08 * (1 - (y + 0.325) / 0.8);
    positions.setXYZ(i, x * lobe, y, z * lobe);
  }
  geometry.computeVertexNormals();
  for (let i = 0; i < 8; i++) {
    const a = (i / 8) * Math.PI * 2;
    const cone = part(geometry, powder, [
      Math.cos(a) * 0.49,
      0.365,
      Math.sin(a) * 0.49,
    ]);
    cone.rotation.y = i * 0.31;
    cone.scale.y = 0.92 + (i % 3) * 0.05;
    group.add(cone);
  }
  const center = part(geometry, powder, [0, 0.365, 0]);
  group.add(center);
  return group;
}
